<template>
  <view class="mes-page">
    <view class="mes-header"><view><view class="mes-title">生产异常</view><view class="mes-description">异常关联实际工单，提交人、工单版本和处置结果可以追溯。主管核对后确认解决。</view></view><button size="mini" :disabled="loading || saving" @click="reload">刷新异常</button></view>
    <view v-if="error" class="mes-error">{{ error }}</view>
    <view v-if="authorized"><view class="mes-toolbar"><input v-model="keyword" class="mes-search" placeholder="批号 / 产品 / 异常分类" @confirm="search" /><view class="mes-filter"><uni-data-select v-model="status" :clear="false" :localdata="statuses" @change="search" /></view><button size="mini" :disabled="loading" @click="search">查询</button><button size="mini" :disabled="saving" @click="newRecord">登记异常</button></view>
      <view class="ops-layout ops-layout-list ops-section"><view class="ops-panel"><view class="ops-panel-title">异常清单 · {{ total }} 条</view><view class="mes-table"><uni-table border :loading="loading" :emptyText="error ? '读取失败，请重新加载' : '暂无生产异常'"><uni-tr><uni-th>分类 / 生产批号</uni-th><uni-th>产品 / 工序</uni-th><uni-th>异常描述</uni-th><uni-th>登记人 / 时间</uni-th><uni-th width="110">状态</uni-th><uni-th width="110">操作</uni-th></uni-tr><uni-tr v-for="row in rows" :key="row._id"><uni-td><view class="ops-cell-stack"><text class="ops-row-title">{{ row.category }}</text><text class="ops-batch">{{ row.batchNo }}</text></view></uni-td><uni-td><view class="ops-cell-stack"><text>{{ row.productName }}</text><text class="ops-table-note">{{ row.processName }}</text></view></uni-td><uni-td><text class="ops-table-note">{{ row.description }}</text></uni-td><uni-td><view class="ops-cell-stack"><text>{{ row.createdName }}</text><text class="ops-table-note">{{ formatDate(row.createdAt) }}</text></view></uni-td><uni-td><text class="ops-status" :class="row.status === 'resolved' ? 'success' : 'warning'">{{ stateName(row.status) }}</text></uni-td><uni-td><button size="mini" :disabled="saving" @click="viewRecord(row)">查看处置</button></uni-td></uni-tr></uni-table></view><view class="mes-pagination"><uni-pagination show-icon :total="total" :page-size="20" :current="page" @change="changePage" /></view></view>
        <operation-drawer :open="showEditor" :title="editing ? '登记生产异常' : '异常详情与处置'" :busy="saving || jobsLoading" @close="showEditor = false"><view class="ops-panel ops-editor-panel"><template v-if="editing"><view class="ops-panel-title">{{ form._id ? '更正异常记录' : '登记生产异常' }}</view><view v-if="!form._id" class="mes-toolbar ops-section"><input v-model="jobKeyword" class="mes-search" placeholder="用完整批号查找工单" @confirm="searchJobs" /><button size="mini" :disabled="jobsLoading || saving" @click="searchJobs">查找工单</button></view><view v-if="jobError" class="mes-error">{{ jobError }}</view><operation-fields v-model="form" :fields="fields" :disabled="saving || jobsLoading" /><view class="mes-footer"><button type="primary" size="mini" :disabled="saving || jobsLoading" @click="save">{{ saving ? '保存中…' : '保存异常' }}</button></view></template><template v-else-if="selected"><view class="ops-panel-title">{{ selected.category }} · {{ selected.batchNo }}<text class="ops-state">{{ stateName(selected.status) }}</text></view><view class="ops-row-detail">{{ selected.productName }} · {{ selected.processName }} · {{ selected.workshopName }}<view>登记 {{ selected.createdName }} · {{ formatDate(selected.createdAt) }} · 工单 v{{ selected.jobVersion }}</view></view><view class="ops-note ops-section">{{ selected.description }}</view><view class="mes-actions ops-section"><button size="mini" @click="openJob(selected.jobId)">查看关联工单</button><button v-if="selected.status === 'open'" size="mini" :disabled="saving" @click="editSelected">更正异常</button></view><template v-if="selected.status === 'open'"><view class="mes-field ops-section"><text class="mes-field-label">处置结果 *</text><textarea v-model="resolution" :disabled="saving" maxlength="8000" placeholder="说明原因、处理措施、核对结果与后续要求" /></view><view class="mes-footer"><button type="primary" size="mini" :disabled="saving" @click="resolve">确认已解决</button></view></template><view v-else class="ops-section"><view class="ops-row-title">处置结果</view><view class="ops-note">{{ selected.resolution }}</view><view class="ops-row-detail">{{ selected.resolvedName }} · {{ formatDate(selected.resolvedAt) }}</view></view></template><view v-if="formError" class="mes-error">{{ formError }}</view><view v-if="notice" class="ops-success">{{ notice }}</view></view> </operation-drawer>
      </view>
    </view>
  </view>
</template>
<script>
import OperationDrawer from '@/components/mes/operations/OperationDrawer.vue';
import OperationFields from '@/components/mes/operations/OperationFields.vue';
import { requireMesAdmin, formatMesDate, confirmMes } from '@/utils/mes-api.js';
import { callOperations, stateName, operationRequest } from '@/utils/operations-admin.js';
function blank() { return { jobId: '', category: '', description: '', enabled: true, changeReason: '' }; }
export default {
  components: { OperationFields, OperationDrawer },
  data() { return { showEditor: false, authorized: false, rows: [], total: 0, page: 1, keyword: '', status: 'open', statuses: [{ value: '', text: '全部状态' }, { value: 'open', text: '待处理' }, { value: 'resolved', text: '已解决' }], loading: false, saving: false, error: '', formError: '', notice: '', form: blank(), editing: true, selected: null, jobs: [], jobKeyword: '', jobsLoading: false, jobError: '', request: null, resolution: '' }; },
  computed: {
    fields() { const fields = [{ key: 'jobId', label: '关联工单', type: 'select', required: true, disabled: !!this.form._id, options: this.jobs.map(row => ({ value: row._id, text: `${row.batchNo} · ${row.processName} · ${row.productName}` })) }, { key: 'category', label: '异常分类', type: 'select', required: true, options: ['质量', '设备', '物料', '安全', '现场卫生', '其他'].map(text => ({ value: text, text })) }, { key: 'description', label: '异常情况', type: 'textarea', maxlength: 8000, required: true, wide: true, placeholder: '写明发现的时间、位置、现象、影响范围和当前处理情况' }]; if (this.form._id) fields.push({ key: 'changeReason', label: '更正原因', type: 'textarea', required: true, wide: true }); return fields; }
  },
  async onLoad(query = {}) { try { await requireMesAdmin(); this.authorized = true; if (query.jobId) { const data = await callOperations('getJob', { id: query.jobId }); this.jobs = [data.job]; this.form.jobId = data.job._id; this.jobKeyword = data.job.batchNo; } await this.reload(); } catch (error) { this.error = error.message; } },
  methods: {
    stateName, formatDate: formatMesDate,
    search() { this.page = 1; this.reload(); },
    changePage(event) { this.page = event.current; this.reload(); },
    openJob(id) { uni.navigateTo({ url: '/pages/mes/operations/job-detail?id=' + encodeURIComponent(id) }); },
    newRecord() { this.showEditor = true; this.form = blank(); this.editing = true; this.selected = null; this.jobs = []; this.jobKeyword = ''; this.request = null; this.formError = ''; this.notice = ''; },
    viewRecord(row) { this.showEditor = true; this.selected = JSON.parse(JSON.stringify(row)); this.editing = false; this.resolution = ''; this.formError = ''; this.notice = ''; },
    editSelected() { this.form = { ...blank(), ...JSON.parse(JSON.stringify(this.selected)), changeReason: '' }; this.jobs = [{ _id: this.selected.jobId, batchNo: this.selected.batchNo, processName: this.selected.processName, productName: this.selected.productName }]; this.editing = true; this.request = null; },
    async reload() { if (this.loading) return; this.loading = true; this.error = ''; try { if (!this.authorized) { await requireMesAdmin(); this.authorized = true; } const data = await callOperations('listExceptions', { page: this.page, pageSize: 20, keyword: this.keyword, status: this.status }); this.rows = data.list || []; this.total = data.total || 0; if (this.selected) { const latest = this.rows.find(row => row._id === this.selected._id); if (latest) this.selected = latest; } } catch (error) { this.rows = []; this.total = 0; this.error = error.message; } finally { this.loading = false; } },
    async searchJobs() { if (this.jobsLoading || this.saving) return; this.jobError = ''; if (!this.jobKeyword.trim()) { this.jobError = '请填写完整批号查找工单。'; return; } this.jobsLoading = true; try { const data = await callOperations('listJobs', { page: 1, pageSize: 50, keyword: this.jobKeyword.trim().toUpperCase() }); const combined = new Map(this.jobs.filter(row => row._id === this.form.jobId).map(row => [row._id, row])); (data.list || []).forEach(row => combined.set(row._id, row)); this.jobs = [...combined.values()]; if (data.total > (data.list || []).length) this.jobError = '匹配较多，请输入更完整的批号。'; else if (!data.total) this.jobError = '没有匹配的工单，请先在工单执行页面建单。'; } catch (error) { this.jobError = error.message; } finally { this.jobsLoading = false; } },
    async save() { if (this.saving) return; this.formError = ''; this.notice = ''; const missing = this.fields.find(field => field.required && !String(this.form[field.key] == null ? '' : this.form[field.key]).trim()); if (missing) { this.formError = '请填写或选择' + missing.label; return; } const payload = { record: this.form, expectedVersion: Number(this.form.version) || 0 }; this.request = operationRequest(this.request, payload); this.saving = true; try { const result = await callOperations('saveException', { ...payload, requestId: this.request.id }); this.form = { ...blank(), ...result, changeReason: '' }; this.viewRecord(result); this.notice = '异常已保存。'; this.request = null; await this.reload(); } catch (error) { this.formError = error.message + (error.code === 409 ? ' 请刷新并重新打开最新异常。' : ' 相同内容可重试。'); } finally { this.saving = false; } },
    async resolve() { if (this.saving || !this.selected) return; this.formError = ''; this.notice = ''; if (!this.resolution.trim()) { this.formError = '请填写处置结果。'; return; } if (!await confirmMes('确认异常已解决', '请核对实际处理和现场情况，确认将该异常标记为已解决。')) return; this.saving = true; try { const result = await callOperations('resolveException', { id: this.selected._id, expectedVersion: this.selected.version, resolution: this.resolution.trim() }); this.selected = result; this.notice = '处置结果已保存，异常已解决。'; await this.reload(); } catch (error) { this.formError = error.message + ' 请刷新并核对最新异常状态。'; } finally { this.saving = false; } }
  }
};
</script>
<style lang="scss" scoped>@import './operations.scss';</style>
